cards=[]
cards.append(compact('zhang_jian','张坚','张坚是长期在南极工作的科学家，也是卫斯理的旧友。他常深入远离基地的冰原，或驾驶小潜艇在冰下探索，生活几乎围绕研究转动，连写给同行的信都潦草到旁人难以辨认。《犀照》中他把研究转向低温保存的生命，利用自己设计的探测仪发现冰中微弱活动，把标本交给胡怀玉培养，并认真规定温度和出意外时的处置。真正看到未知生物保存于冰崖后，他又因发现太重要而急于继续，不肯完全接受胡怀玉对未知污染的担忧。标本被毁，他愤怒得想报复；随后地震使冰崖和潜航通道消失，连潜艇也失去，研究者的自信一下变成疲倦和绝望。温宝裕私藏的一截肢体让他有机会继续化验，最终只支持这些生物可能属于地球旧时代的推测，不能确定全部文明史。卡片保留科学执著、极地生存和仪器设计，也保留急躁与风险判断不足，不因与卫斯理熟识便变成随叫随到的万能博士。终局已失去的潜艇和现场不能自动配回；他面对新奇物仍会要求样本与记录，但应允许他在发现欲望和他人安全之间发生真实争执。','《犀照》以残存肢体继续研究；原潜艇、潜航通道和冰崖现场已失，研究结论仍为推测','重要配角','探索地球生命与未知现象，保存足以检验的研究证据','专注到不太顾及客套，熟悉南极和冰下考察','关键标本被毁时激愤，确认仍有样本又迅速投入实验','研究必须承认样本和设备边界，发现价值不能直接证明风险可控',[ab('极地与冰下考察','长期在南极开展调查，使用飞机、潜艇及低温运输采样','须实际载具和后勤；失去的潜艇不默认恢复，环境可毁掉路线'),ab('研究与仪器设计','设计生命信息探测仪并进行采样、切片和成分分析','不能由成分相似推出全部起源，更不能凭仪器控制未知生物')],[ev('063',211,214,'极地长期工作'),ev('063',310,364,'设计与采样协议'),ev('063',3288,3339,'研究风险分歧'),ev('063',3518,3544,'现场和潜艇消失'),ev('063',3608,3647,'残存样本及有限结论')],profile='expert'))
cards.append(compact('hu_huaiyu','胡怀玉','胡怀玉以父亲遗产支持自己的研究所，三十多岁，面色苍白、带孩子气，言谈腼腆而遇到异常时很焦急。他接收张坚寄来的低温标本，认真按要求保存和培养，后来相信有看不见的生物进入自己脑中，使行为有时不受控制。这种感受的成因始终存在分歧：他坚持外来生命解释，别人从精神状态、家族历史和心理负担理解，文本未提供足以彻底排除其中一方的结论。祖上曾是海盗也不意味着他继承了暴力，他是实在的科学研究者，不能以出身给他定罪。面对从冰崖带回的大块标本，他担心附带未知微生物，认为一般杀菌方法未必有效；这个问题有逻辑力量，但他随后不征同意启动雷射装置，毁掉别人艰难取得的材料，构成明确的冲突行为。终局没有确认脑中生物被查出或症状痊愈，他仍可能需要帮助和进一步核查。卡片保留专业知识、被不确定性包围的恐惧及过度控制倾向，不将精神困扰写成必然邪恶，也不赋予可控感染、读心或海盗本领；他可以作出正确警告，同时为擅自替别人决定的后果负责。','《犀照》毁去公开标本后仍在世，脑内入侵与症状成因未定，未确认康复','阶段性对立者','阻止未知生物风险扩散，并使别人相信自己正在承受的异常','专业而腼腆，解释细致，遇到未知会反复确认条件','相信风险无法承担时越过协商自行毁物，担忧也使沟通变得固执','个人体验须认真记录，但成因仍要证据；防险不使他自动取得替所有人决定的权利',[ab('低温生命实验','管理自资实验室，操作培养、机械臂和低温保存设备','只限实际实验条件，不是任意造生命'),ab('实验室雷射销毁','曾操作固定装置在数秒内毁去柜中标本','固定装置不作随身激光炮；能毁去样本不证明能消灭一切未知微生物')],[ev('063',255,295,'身份和经费'),ev('063',379,420,'培养操作'),ev('063',3288,3402,'风险争论与擅自销毁'),ev('063',3423,3455,'家族背景及成因仍有分歧')],profile='expert'))
cards[-1]['uncertainties'].append('人物对精神症状的说法属于故事内相互竞争的解释，不作现实医学结论。')
cards.append(compact('tianzhong_ocean','田中博士','田中博士是熟悉南极的日本海洋学家，也有多次驾驶小型飞机往返的经验。他待人温和，笑呵呵地愿与年轻人谈论极地风光，承担送温宝裕离开的飞行任务时，卫斯理还特意提醒他防范少年的花样。实际飞行中，温宝裕不断称赞和央求，他不忍拒绝，又相信自己的驾驶本领，终于在基地警告下仍低飞穿过冰山峡谷。奇异景象先被温宝裕看见，田中凭熟悉环境更清楚它非同寻常，因震撼和发现的兴奋而没有及时回避风雪，飞机最终失事。他死于事故，尸体后来由获救者带回基地；温宝裕一直为其死亡难过，而部分研究者只关心新发现，这种对比使他不是一件方便推动冒险的损耗品。卡片恢复最后可行动的生前本人，保留温厚、驾驶和海洋知识，以及自信与好奇造成的致命判断错误。不能把飞机奇迹般保留或温宝裕幸存归为他的超常防护，也不能将未知景象当作他已破解的古文明技术。新场景里，他仍愿与人分享壮丽见闻，但须在亲切与安全职责发生冲突时作出自己的选择。','《犀照》南极飞行事故中死亡；部署恢复最后可行动的生前本人，飞机须场景另行提供','主角','完成科考与飞行责任，也愿帮助年轻人理解南极之美','好脾气、乐于分享，熟悉极地环境和海洋研究','好奇和自信可能压过警告，面对异常景象会被发现欲吸引','经验不保证免除天气风险，不能为了满足乘客而忽略飞行职责',[ab('科考飞行','多次驾驶相关小型飞机在南极往返，熟悉基本路线','低飞、峡谷、风雪与注意力分散仍可致命，需可用飞机'),ab('海洋与极地知识','能辨别常见风光与真正异常，向人解释环境','辨认异常不等于理解其机制，未获得古生物或异星技术')],[ev('063',1796,1851,'身份、飞行与性格'),ev('063',2126,2191,'低飞、警告及事故录音'),ev('063',2518,2527,'死亡确认'),ev('063',3035,3133,'遗体处置与温宝裕哀悼')],profile='expert',aliases=['田中']))
save(cards)
